function beforeUnloadHandler(e) {
    if (dotNetRef) {
        // Synchronous JS interop is not possible here, so we check a mirrored flag.
        // Instead, we always ask the browser and let the .NET side set a flag via the
        // periodic sync approach. A simpler reliable approach: always prevent if enabled.
    }
    e.preventDefault();
}

let handlerAttached = false;

export function enableBeforeUnload(ref) {
    dotNetRef = ref;
    if (!handlerAttached) {
        window.addEventListener("beforeunload", beforeUnloadHandler);
        handlerAttached = true;
    }
}

export function disableBeforeUnload() {
    window.removeEventListener("beforeunload", beforeUnloadHandler);
    handlerAttached = false;
    dotNetRef = null;
}

export function save(key, value) {
    localStorage.setItem(key, value);
}

export function load(key) {
    return localStorage.getItem(key);
}

export function remove(key) {
    localStorage.removeItem(key);
}

